// spec: specs/date-now.md 3.1 · кейс .qa/tests/date-now/DN-08.md
// free (бесплатный). «להפעיל» не нажимается (квота free; находка 11.11 — отдельный баг), покупка не делается — данные не меняются.
import { test, expect } from '@playwright/test';
import path from 'path';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

test.describe('דייט עכשיו — замок бесплатного тарифа → экран покупки', () => {
  test.afterEach(async ({ page }) => saveSession(page, 'free'));

  test('free: замок «שעתיים»/«3 שעות» → «לשדרג ל-Premium» закрывает попап и шит, экран покупки с ценами; «חזרה» → карта без шита; шит открывается снова @iphone @prod-safe (#a5ce54)', async ({ page }) => {
    const setDateNow: string[] = [];
    page.on('request', (r) => { if (r.url().includes('/rpc/set_date_now')) setDateNow.push(r.url()); });
    const sheetTitle = page.getByText('פנוי/ה לדייט עכשיו?');
    const pill = page.getByTestId('date-now-pill');

    await page.goto('/map');
    for (const chip of [/^שעתיים/, /^3 שעות/]) {
      await expect(pill).toBeVisible({ timeout: 30_000 });
      await pill.click();
      await expect(sheetTitle).toBeVisible();
      await page.getByRole('button', { name: chip }).click();
      const upsell = page.getByRole('dialog').filter({ has: page.getByRole('button', { name: 'לשדרג ל-Premium' }) });
      await expect(upsell.getByRole('button', { name: 'לא עכשיו' })).toBeVisible();

      await upsell.getByRole('button', { name: 'לשדרג ל-Premium' }).click();
      // Чистый экран покупки: попап и шит закрыты, периоды и цены видны сразу (AC 10; реджекты Р4/Р5).
      await page.waitForURL(/\/paywall/);
      await expect(sheetTitle).toBeHidden();
      await expect(page.getByRole('button', { name: 'לא עכשיו' })).toHaveCount(0);
      const plans = page.getByRole('radio', { name: /₪\d+(\.\d+)? לחודש/ });
      await expect(plans.first()).toBeVisible();
      expect(await plans.count()).toBeGreaterThanOrEqual(3);

      // «חזרה» → карта без шита (AC 10).
      await page.getByRole('button', { name: 'חזרה' }).click();
      await page.waitForURL(/\/map/);
      await expect(pill).toBeVisible();
      await expect(sheetTitle).toBeHidden();
    }

    // Повторное «דייט עכשיו» открывает шит нормально; закрыть «לא עכשיו».
    await pill.click();
    await expect(sheetTitle).toBeVisible();
    await page.getByRole('button', { name: 'לא עכשיו' }).click();
    await expect(sheetTitle).toBeHidden();
    expect(setDateNow, 'режим не включался').toHaveLength(0);
  });
});
